	Coord
	Label string
}

var Origin = Marker{
	Coord: Coord{X: 0, Y: 0},
	Label: "origin",
}' To fix the code, use the Remove embedded field type Coord quick-fix. After the quick-fix is applied: 'var Origin = Marker{
	X: 0, Y: 0,
	Label: "origin",
}' Inspection ID: GoFixEmbedLit

