    func TestSomething(t *testing.T) {
    	ctx, cancel := context.WithCancel(context.Background())
    	defer cancel()

    	if err := work(ctx); err != nil {
    		t.Fatal(err)
    	}
    }

To fix the code, use the **Replace context.WithCancel with t.Context** quick-fix.

**After the quick-fix is applied:**


    func TestSomething(t *testing.T) {
    	ctx := t.Context()

    	if err := work(ctx); err != nil {
    		t.Fatal(err)
    	}
    }

Inspection ID: GoFixTestingContext

